function openModal(title,body){selected=null;$('#modalContent').innerHTML='<div class="modal-header"><h2>'+esc(title)+'</h2><button class="close" data-close aria-label="Kapat">×</button></div><div class="modal-body">'+body+'</div>';if(!$('#modal').open)$('#modal').showModal();}
function detailFields(r){return [['Barkod',r.barcode||'Henüz yok'],['Versiyon',r.version??'—'],['Numune kodu',r.sampleCode||r.code||'Eşleştirme gerekli'],['Ana model',r.mainCode||'—'],['Kalıp No',r.patternNo||'Henüz boş'],['Marka / Departman',[r.brand,r.department].filter(Boolean).join(' / ')],['Ara işlem',r.erp?.intermediateLabel||'Seçilmemiş / bilgi yok'],['Barkod başlangıcı',date(r.erp?.barcodeCreatedAt)],['Beden / Renk',[r.body,r.color].filter(Boolean).join(' / ')||'—'],['ERP aşaması',stage(r.erpStage).name]].map(([label,value])=>'<div><small>'+esc(label)+'</small>'+esc(value)+'</div>').join('');}
function movementTitle(m){if(normal(m.process)==='kesim'&&m.kind===100)return 'Kesim okutuldu → '+stage(m.workflowStage||'queue').name;if(normal(m.process)==='dikim'&&m.kind===0)return 'Dikime giden okutuldu → Dikimde';if(normal(m.process)==='dikim'&&m.kind===1)return 'Dikimden gelen okutuldu → Kalitede';return (m.process||'Hareket')+' · '+stage(m.workflowStage||m.stage).name;}
